import test from 'node:test';
import assert from 'node:assert/strict';
import { Window } from 'happy-dom';
import { coverSettings, coverFingerprint, inspectCoverJPEG, validatePreparedCover, createPublicationCover } from './dist/publication-cover.js';
import { normalizePublication, buildPublicationPackage } from './dist/publication.js';
import { renderPublicationPanel, mountPublicationPanel } from './dist/publication-ui.js';
// Genuine 625x1000 RGB JPEG, generated by Pillow. No external test dependency.
const JPEG = '';
const bytes = () => new Uint8Array(Buffer.from(JPEG, 'base64'));
const book = () => ({ id: 'cover-test', title: '검증할 표지', author: '저자', description: '소개', language: 'ko', theme: 'sage', chapters: [{ id: 'one', title: '본문', content: '완성된 본문' }] });
const metadata = () => normalizePublication({ channel: 'domestic', publisher: '출판사', publicationDate: '2026-10-20', price: '5000', coverWidth: 625, coverHeight: 1000 });
const prepared = (p,m) => ({ bytes: bytes(), fingerprint: coverFingerprint(p,m), warnings: [] });

test('cover profiles distinguish recommended KDP dimensions from customizable domestic presets', () => {
  assert.deepEqual([coverSettings({channel:'kdp',coverWidth:800,coverHeight:1200}).width,coverSettings({channel:'kdp'}).height],[1600,2560]);
  assert.equal(coverSettings().height,2400);
  for (const options of [{coverWidth:4097},{coverHeight:900},{coverWidth:1600,coverHeight:1500},{coverWidth:Infinity},{coverWidth:800.5}]) assert.throws(()=>coverSettings(options));
});
test('JPEG validation reads actual dimensions, rejects broken or stale covers and claimed dimensions', () => {
  const facts=inspectCoverJPEG(bytes()); assert.equal(facts.width,625); assert.equal(facts.height,1000); assert.equal(facts.components,3);
  const p=book(), m=metadata(), cover=prepared(p,m);
  assert.equal(validatePreparedCover(cover,p,m).mime,'image/jpeg');
  assert.throws(()=>inspectCoverJPEG(new Uint8Array([1,2,3])),/JPEG/);
  assert.throws(()=>validatePreparedCover({...cover,bytes:bytes().slice(0,80)},p,m));
  assert.throws(()=>validatePreparedCover({...cover,width:1600,height:2400},p,{...m,coverWidth:1600,coverHeight:2400}),/다시 생성/);
  assert.throws(()=>validatePreparedCover(cover,{...p,title:'새 제목'},m),/변경/);
  assert.throws(()=>validatePreparedCover(cover,p,{...m,publisher:'새 발행처'}),/변경/);
  const forged={...cover,fingerprint:coverFingerprint(p,{...m,coverWidth:1600,coverHeight:2400})};
  assert.throws(()=>validatePreparedCover(forged,p,{...m,coverWidth:1600,coverHeight:2400}),/크기/);
});
test('publication package includes only an actual matching JPEG and validation report', async () => {
  const p=book(),m=metadata(); const result=await buildPublicationPackage(p,m,{preparedCover:prepared(p,m)});
  assert.ok(result.files.includes('cover.jpg')); assert.ok(result.files.includes('cover-report.json')); assert.equal(result.files.length,16);
  await assert.rejects(buildPublicationPackage({...p,title:'바뀐 제목'},m,{preparedCover:prepared(p,m)}),/다시 생성/);
  await assert.rejects(createPublicationCover(p,m,{document:null}),/브라우저/);
});
test('cover export ignores late generation after panel disposal and manuscript changes', async () => {
  for(const action of ['dispose','edit']) {
    const win=new Window({settings:{disableJavaScriptEvaluation:true}}), p=book(); p.publication=metadata();
    win.document.body.innerHTML=renderPublicationPanel(p); const panel=win.document.querySelector('.publication-panel');
    const downloads=[]; let resolveCover; const pending=new Promise(resolve=>resolveCover=resolve);
    const mount=mountPublicationPanel(panel,{getProject:()=>p,onSave:m=>p.publication=m,download:(...args)=>downloads.push(args),makeCover:()=>pending});
    try {
      panel.querySelector('[data-publication-action="cover"]').click();
      await new Promise(resolve=>setTimeout(resolve,0));
      if(action==='dispose') mount.dispose(); else p.title='생성 중 바뀐 제목';
      resolveCover(prepared(book(),metadata())); await new Promise(resolve=>setTimeout(resolve,0));
      assert.equal(downloads.length,0);
      if(action==='edit') assert.match(panel.querySelector('.publication-message').textContent,/변경/);
    } finally {mount.dispose(); await win.happyDOM.close();}
  }
});
